import { readFileSync } from "node:fs";
import path from "node:path";
import type { Page, Route } from "@playwright/test";

/**
 * Helpers for the player tests. The media is generated by scripts/make-fixtures.mjs into
 * e2e/fixtures/ and served through request interception, with byte ranges, so video
 * elements can seek. Timings here mirror that script.
 */
export const FIXTURES = path.join(__dirname, "fixtures");

export const CUES = {
  c001: { start: 1.0, end: 2.2, text: "A grey card slides in from the left." },
  c002: { start: 3.6, end: 4.6, text: "The card turns over & shows a clock." },
  x001: { start: 2.5, pause: 1.5, text: "Two words appear on the card: still here." },
} as const;

/** A page on another origin that embeds the player with one script tag. */
export const EMBED = "http://embed.test";
/**
 * Where that page loads player.js from. The browser won't let a public page reach the
 * loopback test server, so this origin relays the server's real response, headers and
 * all: the module still loads only if the site's CORS headers allow it.
 */
export const CDN = "http://cdn.test";

const TYPES: Record<string, string> = {
  ".mp4": "video/mp4",
  ".m4a": "audio/mp4",
  ".vtt": "text/vtt; charset=utf-8",
  ".wav": "audio/wav",
  ".jpg": "image/jpeg",
};

/** Serves a file from disk, honouring a Range header (206), or a 404 when it isn't there. */
export async function serveFile(route: Route, file: string, headers: Record<string, string> = {}): Promise<void> {
  let body: Buffer;
  try {
    body = readFileSync(file);
  } catch {
    await route.fulfill({ status: 404, contentType: "text/plain", body: "not found" });
    return;
  }
  const base = { "content-type": TYPES[path.extname(file)] ?? "application/octet-stream", "accept-ranges": "bytes", ...headers };
  const range = /bytes=(\d*)-(\d*)/.exec(route.request().headers()["range"] ?? "");
  if (!range) {
    await route.fulfill({ status: 200, headers: { ...base, "content-length": String(body.length) }, body });
    return;
  }
  let start = range[1] ? Number(range[1]) : 0;
  let end = range[2] ? Number(range[2]) : body.length - 1;
  if (!range[1] && range[2]) {
    start = Math.max(0, body.length - Number(range[2]));
    end = body.length - 1;
  }
  end = Math.min(end, body.length - 1);
  if (start > end) {
    await route.fulfill({ status: 416, headers: { "content-range": `bytes */${body.length}` } });
    return;
  }
  await route.fulfill({
    status: 206,
    headers: { ...base, "content-range": `bytes ${start}-${end}/${body.length}`, "content-length": String(end - start + 1) },
    body: body.subarray(start, end + 1),
  });
}

/** Serves requests under `prefix` from e2e/fixtures/, by the path after the prefix. */
export async function routeFixtures(page: Page, pattern: string, prefix: string): Promise<void> {
  await page.route(pattern, (route) => {
    const rel = decodeURIComponent(new URL(route.request().url()).pathname.slice(prefix.length));
    if (rel.includes("..")) return route.fulfill({ status: 400, body: "" });
    return serveFile(route, path.join(FIXTURES, rel));
  });
}

export type PlayerAttrs = Partial<
  Record<"src" | "descriptions" | "described-audio" | "extended" | "cue-audio-base" | "captions" | "poster" | "mode" | "label" | "crossorigin", string>
>;

/** Every input the player takes, from the fixtures. */
export const FULL: PlayerAttrs = {
  src: "/fx/video.mp4",
  descriptions: "/fx/descriptions.vtt",
  "described-audio": "/fx/described-audio.m4a",
  extended: "/fx/extended.vtt",
  "cue-audio-base": "/fx/audio/",
  captions: "/fx/captions.vtt",
  poster: "/fx/poster.jpg",
  label: "Test pattern, described",
};

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");

/**
 * Opens a plain page on http://embed.test that loads /player.js from the site under test,
 * the way another site would, with the given attributes on one <lull-player>.
 */
export async function openEmbed(page: Page, baseURL: string, attrs: PlayerAttrs = FULL): Promise<void> {
  const attrText = Object.entries(attrs)
    .map(([k, v]) => ` ${k}="${esc(String(v))}"`)
    .join("");
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Embed test</title>
<script type="module" src="${CDN}/player.js"></script>
<style>body{margin:0;padding:24px;background:#fff;color:#111;font-family:system-ui,sans-serif}main{max-width:960px;margin:0 auto}</style>
</head><body><main><h1>Embedded player</h1><lull-player${attrText}></lull-player></main></body></html>`;
  await routeFixtures(page, `${EMBED}/fx/**`, "/fx/");
  await page.route(`${CDN}/player.js`, async (route) => {
    const res = await page.request.get(`${baseURL}/player.js`);
    await route.fulfill({ status: res.status(), headers: res.headers(), body: await res.body() });
  });
  await page.route(`${EMBED}/`, (route) => route.fulfill({ status: 200, contentType: "text/html; charset=utf-8", body: html }));
  await page.goto(`${EMBED}/`);
  await page.waitForFunction(() => !!customElements.get("lull-player"));
}

/** The player's state snapshot. */
export function playerState(page: Page) {
  return page.locator("lull-player").evaluate((el) => (el as unknown as { state: Record<string, unknown> }).state);
}

/** The video inside the player: currentTime and paused. */
export function videoClock(page: Page) {
  return page.locator("lull-player").evaluate((el) => {
    const v = el.shadowRoot?.querySelector("video") as HTMLVideoElement;
    return { t: v.currentTime, paused: v.paused, muted: v.muted, ready: v.readyState };
  });
}

/** Waits until the video has data and the descriptions are in. */
export async function waitReady(page: Page): Promise<void> {
  await page.waitForFunction(() => {
    const el = document.querySelector("lull-player") as (HTMLElement & { state: { video: string; descriptions: string } }) | null;
    const v = el?.shadowRoot?.querySelector("video") as HTMLVideoElement | null;
    return !!el && !!v && v.readyState >= 2 && el.state.video === "ready" && el.state.descriptions !== "loading";
  });
}
